-- Hindi Word EFFICIENCY TEST 8, TEST 9 and TEST 10: new papers (25 Nov 2026). The old ones asked the same kinds of
-- questions as Tests 5-7 (font size/colour, Change Case UPPERCASE, numbering, subscript, sort, Replace All, Page Break,
-- Insert Table, a symbol, header + page number, watermark, page colour, orientation + margins). Every new question asks
-- for a Word 2013 tool or option that no other Word Efficiency paper uses, and no question repeats across the papers,
-- over the tabs of the exam: HOME, INSERT, DESIGN, PAGE LAYOUT and TABLE TOOLS (DESIGN and LAYOUT). VIEW is not asked:
-- the view, zoom, ruler and gridlines are not saved with the document, so they cannot be marked.
--   TEST 8:  Format Painter, Sentence case, Dotted underline, Theme font colour, Square bullets, Top Border, page number
--            (top right, i ii iii), Insert Above + Merge Cells, AutoFit Window, Grid Table 6 Colorful, Total Row,
--            page border on the first page only, Letter, Mirrored margins, Blank Page.
--   TEST 9:  lowercase, Position Raised, Dashed underline, Decrease Indent, Diamond bullets, Sort a list Z-A, Page X of
--            Y, Text Direction, Formula =SUM(ABOVE), Cell Margins, List Table 3, horizontal custom watermark, Three
--            columns, Office 2003 Default margins, B5 (JIS).
--   TEST 10: Character Scale 150%, remove a highlight, All caps, numbering i ii iii, line spacing 3.0, Footer Blank
--            (Three Columns), Insert Left, row Height, Distribute Columns, Plain Table 4, Banded Columns, red All
--            Borders, theme page colour, Statement, Spacing After from PAGE LAYOUT.
-- Each test gets a NEW version with its own practice document (students' earlier attempts stay on their own version
-- with their marks), hand-written checks, Hindi solutions and the Model Answer solved in the real editor; results are
-- published automatically. The tools the questions need are switched on in the new versions' editor settings.
-- Generated by scripts/build-hindi-word-tests-8-10-v2-migration.mjs. Safe to run twice (a test already on its new paper
-- is skipped).
begin;

create temporary table new_paper (title text, matter jsonb, questions jsonb, model jsonb, tools jsonb) on commit drop;
insert into new_paper values
 ($q$EFFICIENCY TEST 8$q$, $q${"schemaVersion":"1","language":"Hindi","paragraphs":[{"id":"matter-p-1","type":"paragraph","paragraphNumber":1,"listGroup":null,"runs":[{"text":"fMftVy lk{kjrk vkt gj ukxfjd ds fy, vko';d gSA v‚uykbu QkWeZ Hkjuk] fcy tek djuk vkSj ljdkjh ;kstukvksa dh tkudkjh ysuk vc eksckby vkSj dEI;wVj ls gh gksrk gSA tks fo|kFkhZ dEI;wVj dk fu;fer vH;kl djrs gSa] os ijh{kk esa le; ij lHkh iz'u gy dj ysrs gSaA","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":14,"fontFamily":"Kruti Dev 010"}],"alignment":"justify","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8},{"id":"matter-p-2","type":"paragraph","paragraphNumber":2,"listGroup":null,"runs":[{"text":"A word processor saves time because a document can be corrected and printed again without typing it from the beginning. Spelling, fonts and spacing can be changed with a single click.","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8},{"id":"matter-p-3","type":"paragraph","paragraphNumber":3,"listGroup":null,"runs":[{"text":"Keyboard shortcuts make the work faster. Ctrl+B makes text bold, Ctrl+I makes it italic and Ctrl+S saves the document on the computer.","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8},{"id":"matter-p-4","type":"paragraph","paragraphNumber":4,"listGroup":null,"runs":[{"text":"PRACTICE DAILY FOR BETTER SPEED. CHECK EVERY ANSWER BEFORE YOU SUBMIT THE PAPER.","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"line