y":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8},{"id":"matter-p-11","type":"table","rows":[["S.No.","Name","Subject","Marks"],["1","Ramesh","Hindi","72"],["2","Kiran","English","65"],["3","Suresh","Computer","88"],["4","Neha","Maths","79"]],"cellFonts":[["Segoe UI","Segoe UI","Segoe UI","Segoe UI"],["Segoe UI","Segoe UI","Segoe UI","Segoe UI"],["Segoe UI","Segoe UI","Segoe UI","Segoe UI"],["Segoe UI","Segoe UI","Segoe UI","Segoe UI"],["Segoe UI","Segoe UI","Segoe UI","Segoe UI"]],"cellSizes":[[12,12,12,12],[12,12,12,12],[12,12,12,12],[12,12,12,12],[12,12,12,12]]},{"id":"matter-p-12","type":"paragraph","paragraphNumber":12,"listGroup":null,"runs":[{"text":"","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8}],"warnings":[],"formattingSummary":{"paragraphs":12,"runs":12,"italicParagraphs":0,"justifiedParagraphs":1,"listItems":4,"tables":1,"fonts":["Kruti Dev 010","Segoe UI"]}}$q$::jsonb, $q$[{"number":1,"instruction":"Format Painter से \"SAMRADHI CLASSES, JAIPUR\" लाइन की फॉर्मेटिंग \"Computer Efficiency Test 2026\" लाइन पर लगाइए।","marks":1.66,"criteria":[{"rule":"words","kind":"body","place":9,"props":{"bold":[true],"color":["0070C0"],"fontSize":[16]}}],"solution":"1. \"SAMRADHI CLASSES, JAIPUR\" लाइन को सेलेक्ट करें।\n2. HOME → **Format Painter** (ब्रश) पर क्लिक करें।\n3. \"Computer Efficiency Test 2026\" लाइन पर माउस से ड्रैग करके उसे सेलेक्ट करें।\n\nजाँच: दूसरी लाइन भी बोल्ड, नीली, साइज 16।"},{"number":2,"instruction":"चतुर्थ पैराग्राफ (PRACTICE DAILY…) को Change Case से Sentence case कीजिए।","marks":1.66,"criteria":[{"rule":"text","kind":"body","place":3,"find":"Practice daily for better speed.","caseSensitive":true},{"rule":"text","kind":"body","place":3,"find":"Check every answer before you submit the paper.","caseSensitive":true}],"solution":"1. चौथा पैराग्राफ सेलेक्ट करें।\n2. HOME → **Change Case (Aa ▾)** → **Sentence case.**\n\nजाँच: हर वाक्य का पहला अक्षर बड़ा, बाकी छोटे।"},{"number":3,"instruction":"तृतीय पैराग्राफ (Keyboard shortcuts…) को Dotted अंडरलाइन दीजिए।","marks":1.66,"criteria":[{"rule":"words","kind":"body","place":2,"props":{"underline":[true],"underlineStyle":["dotted"]}}],"solution":"1. तीसरा पैराग्राफ सेलेक्ट करें।\n2. HOME → **Underline ▾** → **डॉटेड लाइन (·····)**।\n\nजाँच: पूरे पैराग्राफ के नीचे बिंदुओं वाली लाइन।"},{"number":4,"instruction":"दी गई सूची (Clipboard, Font…) की बुलेट्स को Filled square (■) बुलेट में बदलिए।","marks":1.66,"criteria":[{"rule":"value","kind":"body","place":4,"target":"blocks.0.attrs.listStyle","spec":["bullet-square"]},{"rule":"value","kind":"body","place":5,"target":"blocks.0.attrs.listStyle","spec":["bullet-square"]},{"rule":"value","kind":"body","place":6,"target":"blocks.0.attrs.listStyle","spec":["bullet-square"]},{"rule":"value","kind":"body","place":7,"target":"blocks.0.attrs.listStyle","spec":["bullet-square"]}],"solution":"1. सूची के चारों आइटम सेलेक्ट करें।\n2. HOME → **Bullets ▾** → **■ Filled square bullets**।\n\nजाँच: चारों आइटम के आगे ■।"},{"number":5,"instruction":"द्वितीय पैराग्राफ (A word processor…) पर केवल Top Border (ऊपर की बॉर्डर) लगाइए।","marks":1.66,"criteria":[{"rule":"value","kind":"body","place":1,"target":"blocks.0.attrs.border","spec":{"regex":"(^|sides:)top$"}}],"solution":"1. दूसरे पैराग्राफ में क्लिक करें।\n2. HOME → **Borders ▾** → **Top Border**।\n\nजाँच: पैराग्राफ के केवल ऊपर एक लाइन।"},{"number":6,"instruction":"Page Number → Top of Page → Plain Number 3 (दाईं ओर) लगाइए और Format Page Numbers से फॉर्मेट i, ii, iii कीजिए।","marks":1.66,"criteria":[{"rule":"run","kind":"header","props":{"field":{"regex":"^page-number\\|top\\|right"},"text":{"regex":"^\\s*i\\s*$"}}}],"solution":"1. INSERT → **Page Number ▾** → **Top of Page** → **Plain Number 3**।\n2. INSERT → **Page Number ▾** → **Format Page Numbers…** → Number format **i, ii, iii, …** → **OK**।\n3. **Close Header and Footer**।\n\nजाँच: हेडर में दाईं ओर पेज नंबर i।"},{"number":7,"instruction":"टेबल की पहली रो के ऊपर एक नई रो इन्सर्ट (Insert Above) कीजिए, उसके सभी सेल Merge करके उसमें \"RESULT SHEET\" लिखिए।","marks":1.66,"criteria":[{"rule":"table","place":0,"rowCount":6,"headerAt":{"0":"RESULT SHEET"},"onlyRow":0,"cellProps":{"colspan":[4]}}],"solution":"1. टेबल की पहली रो (S.No.…) में क्लिक करें।\n2. TABLE TOOLS → **LAYOUT** → **Insert Above**।\n3. नई रो सेलेक्ट करें → LAYOUT → **Merge Cells**।\n4. उसमें **RESULT SHEET** टाइप करें।\n\nजाँच: टेबल के ऊपर एक चौड़ी रो में RESULT SHEET।"},{"number":8,"instruction":"टेबल को AutoFit → AutoFit Window कीजिए।","marks":1.66,"criteria":[{"rule":"table","place":0,"attrs":{"tableLayout":["window"]}}],"solution":"1. टेबल में क्लिक करें।\n2. TABLE TOOLS → **LAYOUT** → **AutoFit ▾** → **AutoFit Window**।\n\nजाँच: टेबल पूरे पेज की चौड़ाई में।"},{"number":9,"instruction":"टेबल पर Table Style \"Grid Table 6 Colorful - Accent 1\" लगाइए।","marks":1.66,"criteria":[{"rule":"table","place":0,"attrs":{"tableStyle":["grid-6-colorful-accent-1"]}}],"solution":"1. टेबल में क्लिक करें।\n2. TABLE TOOLS → **DESIGN** → Table Styles ▾ → Grid Tables में **Grid Table 6 Colorful - Accent 1**।\n\nजाँच: नीली लाइनों और नीले अक्षरों वाली टेबल।"},{"number":10,"instruction":"Table Style Options में Total Row चालू (✔) कीजिए।","marks":1.66,"criteria":[{"rule":"table","place":0,"attrs":{"totalRow":[true]}}],"solution":"1. टेबल में क्लिक करें।\n2. TABLE TOOLS → **DESIGN** → Table Style Options में **Total Row** ✔।\n\nजाँच: टेबल की अंतिम रो अलग (बोल्ड) दिखे।"},{"number":11,"instruction":"पेज पर Box पेज बॉर्डर दीजिए जो केवल पहले पेज पर हो (Apply to: This section - First page only)।","marks":1.66,"criteria":[{"rule":"value","target":"pageLayout.border","spec":{"regex":"apply:s1-first"}}],"solution":"1. DESIGN → **Page Borders**।\n2. Setting **Box** → Apply to **This section - First page only** → **OK**।\n\nजाँच: बॉर्डर केवल पहले पेज पर।"},{"number":12,"instruction":"पेज का Size Letter कीजिए।","marks":1.66,"criteria":[{"rule":"value","target":"pageLayout.aspectRatio","spec":{"regex":"^21\\.59 ?/ ?27\\.94$"}}],"solution":"1. PAGE LAYOUT → **Size ▾** → **Letter** (21.59 cm × 27.94 cm)।\n\nजाँच: पेज Letter साइज़ का।"},{"number":13,"instruction":"पेज के Margins Mirrored कीजिए।","marks":1.66,"criteria":[{"rule":"value","target":"pageLayout.padding","spec":{"regex":"^25\\.4mm 25\\.4mm 25\\.4mm 31\\.8mm$"}}],"solution":"1. PAGE LAYOUT → **Margins ▾** → **Mirrored** (Inside 3.18 cm, Outside 2.54 cm)।\n\nजाँच: अंदर की ओर का मार्जिन थोड़ा चौड़ा।"},{"number":14,"instruction":"डॉक्यूमेंट के अंत में (टेबल के बाद) एक Blank Page इन्सर्ट कीजिए।","marks":1.66,"criteria":[{"rule":"anyOf","criteria":[{"rule":"value","kind":"body","place":11,"target":"blocks.0.attrs.kind","spec":["blank-page"]},{"rule":"value","kind":"body","place":12,"target":"blocks.0.attrs.kind","spec":["blank-page"]}]}],"solution":"1. टेबल के नीचे, डॉक्यूमेंट के अंत में क्लिक करें।\n2. INSERT → **Blank Page**।\n\nजाँच: अंत में एक खाली पेज।"},{"number":15,"instruction":"प्रथम पैराग्राफ (हिंदी) का फॉन्ट कलर Theme Colors से \"Green, Accent 6, Darker 50%\" कीजिए।","marks":1.76,"criteria":[{"rule":"words","kind":"body","place":0,"props":{"color":["385724"],"fontFamily":{"regex":"^kruti dev"}}}],"solution":"1. पहला (हिंदी) पैराग्राफ सेलेक्ट करें।\n2. HOME → **Font Color ▾** → Theme Colors में हरे कॉलम का सबसे नीचे वाला रंग **Green, Accent 6, Darker 50%**।\n\nजाँच: पैराग्राफ गहरे हरे रंग में, फॉन्ट Kruti Dev 010 ही रहे।"}]$q$::jsonb, $q${"schemaVersion":"2","blocks":[{"id":"block-0","type":"header","alignment":"right","runs":[{"text":"i","bold":false,"italic":false,"underline":false,"underlineStyle":null,"underlineColor":null,"underlineThickness":null,"underlineWordsOnly":false,"strike":false,"doubleStrike":false,"superscript":false,"subscript":false,"smallCaps":false,"allCaps":false,"hidden":false,"outline":false,"emb